"""Original editorial design and motion-led homepage for Future Cloud Campus."""
from enhancements import review_cards, social_icons
from pricing_content import pricing_preview
from campus_people import teaser as faculty_teaser


def studio_home(button, accordions, faq):
    subjects=[('mathematics','Mathematics','Find the logic. See the pattern.','MATHS'),('english','English','Find your words. Build your voice.','LANGUAGE'),('science','Science','Ask why. Explore what happens.','DISCOVERY'),('computer-it','Computer & IT','Think it through. Make it work.','COMPUTING')]
    cards=''.join(f'''<a class="studio-subject studio-reveal" href="/{slug}/" data-studio-card><div class="studio-subject-top"><span>{label}</span><span class="studio-card-mark" aria-hidden="true">✦</span></div><div class="studio-subject-art"><img src="/assets/pages/{slug}.svg" width="480" height="360" loading="lazy" alt=""></div><div class="studio-subject-copy"><h3>{title}</h3><p>{copy}</p><span class="studio-subject-link">Explore the subject</span></div></a>''' for slug,title,copy,label in subjects)
    return f'''<div data-studio-home>
    <section class="studio-hero" aria-labelledby="studio-title"><div class="studio-hero-grid shell"><div class="studio-hero-copy"><span class="studio-label studio-enter">ONE CAMPUS. ENDLESS LEARNING.</span><h1 id="studio-title"><span class="studio-title-line"><span>Personal online</span></span><span class="studio-title-line"><span>tutoring.</span></span><span class="studio-title-line"><span><em>A clearer path</em></span></span><span class="studio-title-line"><span><em>forward.</em></span></span></h1><p class="studio-enter">One-to-one support for school subjects and Quran learning. Start with your child’s course, pace and goals.</p><div class="hero-actions studio-enter">{button('Book a Free Demo')}{button('Explore subjects','#campus','secondary')}</div><span class="studio-hero-note studio-enter">School subjects · Quran Education · Study resources</span></div><figure class="studio-stage" data-studio-scene aria-label="An imaginative online learning scene"><div class="studio-scene-orbit orbit-one" aria-hidden="true"></div><div class="studio-scene-orbit orbit-two" aria-hidden="true"></div><div class="studio-stage-inner"><div class="studio-stage-image"><img src="/assets/hero-live-learning.webp" width="1280" height="960" fetchpriority="high" alt="A sculptural online classroom with a tutor on a laptop, books, pencil and science model"></div><span class="studio-orb orb-cyan" aria-hidden="true"></span><span class="studio-orb orb-coral" aria-hidden="true"></span><span class="studio-float-tag tag-a" aria-hidden="true">What if?</span><span class="studio-float-tag tag-b" aria-hidden="true">Aha!</span><span class="studio-asterisk" aria-hidden="true">✺</span></div><figcaption>YOUR NEXT CHAPTER STARTS WITH A QUESTION.</figcaption></figure></div><div class="shell studio-hero-bottom"><span>Personal pace. Shared possibilities.</span><a href="#campus" class="studio-scroll-link">Scroll to discover <span aria-hidden="true">●</span></a><span class="studio-hero-coordinate" aria-hidden="true">FCC / LEARNING IN MOTION</span></div></section>
    <section class="studio-subjects studio-space" id="campus"><div class="shell"><div class="studio-section-top studio-reveal"><div><span class="studio-label">FOLLOW YOUR CURIOSITY</span><h2>Find your <em>spark.</em></h2></div><a class="btn secondary" href="/subjects/">All academic subjects</a></div><div class="studio-subject-grid">{cards}</div><div class="studio-subject-foot studio-reveal"><p>From first foundations to exam preparation.</p><div><a href="/curricula/">Find your curriculum</a><a href="/test-prep/">Plan for an exam</a><a href="/learning-levels/">Explore learning levels</a></div></div></div></section>
    <section class="shell studio-space home-steps" aria-labelledby="home-steps-title"><div class="studio-section-top"><div><span class="studio-label">HOW LESSONS COME TOGETHER</span><h2 id="home-steps-title">A clear start.<br><em>Three simple steps.</em></h2></div><a class="studio-inline-link" href="/how-it-works/">Explore how it works</a></div><ol class="home-step-grid"><li><span class="home-step-number">01</span><h3>Share your starting point.</h3><p>Choose a subject, school course and a learning goal. Tell us the times that suit your family.</p><a href="/learning-levels/">Find your learning pathway ↗</a></li><li><span class="home-step-number">02</span><h3>Discuss a tutor match.</h3><p>Talk through the learning needs and agree a first lesson, subject to tutor availability.</p><a href="/tutors/">Explore tutor profiles ↗</a></li><li><span class="home-step-number">03</span><h3>Learn. Practise. Review.</h3><p>Work through an idea, try it independently and identify a useful next step.</p><a href="/try-a-lesson/">Try a mini lesson ↗</a></li></ol></section>
    {faculty_teaser()}<section class="studio-quran studio-space"><div class="shell studio-quran-grid"><div class="studio-quran-picture studio-reveal"><div class="studio-quran-halo" aria-hidden="true"></div><img src="/assets/quran.svg" width="500" height="350" alt="An illustrated open Quran" loading="lazy"><span class="studio-quran-insignia" aria-hidden="true">✦</span></div><div class="studio-quran-copy studio-reveal"><span class="studio-label">OUR QURAN LEARNING SPACE</span><h2>Read with care.<br><em>Learn with meaning.</em></h2><p>Explore Quran reading, Urdu translation and guided foundation lessons in a dedicated, calm study space.</p><div class="studio-quran-links"><a href="/noorani-qaida/#learning-library">Noorani Qaida</a><a href="/tajweed/#learning-library">Tajweed & Makharij</a><a href="/islamic-studies/#learning-library">Islamic Studies</a></div><div class="hero-actions">{button('Quran with Urdu translation','/quran-reading/#quran-reader','light')}<a class="studio-inline-link" href="/quran-education/">Explore Quran Education</a></div></div></div></section>
    <section class="shell studio-family studio-space"><div class="studio-section-top studio-reveal"><div><span class="studio-label">FAMILY FEEDBACK</span><h2>Small breakthroughs.<br><em>Meaningful stories.</em></h2></div><a class="studio-inline-link" href="/reviews/">Visit family feedback</a></div>{review_cards(6)}</section>
    <div class="studio-plans">{pricing_preview()}</div>
    <section class="shell studio-faq studio-space"><div><span class="studio-label">LET’S MAKE THINGS CLEAR</span><h2>Good<br><em>questions.</em></h2><a class="studio-inline-link" href="/faq/">All frequently asked questions</a></div>{accordions(faq[:4])}</section>
    <section class="studio-finale"><div class="shell"><span class="studio-label">THE NEXT CHAPTER IS YOURS</span><h2 class="studio-reveal">Ready to<br><em>see what’s possible?</em></h2><div class="studio-finale-bottom"><p>Bring a question. Share a goal.<br>Let’s find your child’s starting point.</p>{button('Book a Free Demo','/book-a-demo/','light')}</div><div class="studio-finale-social">{social_icons(True)}</div></div><span class="studio-finale-orbit" aria-hidden="true"></span></section>
    </div>'''
